function wandPrimaryAmount(i,amount){const m=defs[i.type].mechanic;return amount*(1+(m.ownAttack||0)+((m.amulets||m.syndicate)?swordPartner(i):0))}
function wandQueue(i,damage,pierce,time){const q=s.wandProjectiles||(s.wandProjectiles=[]);if(damage>0&&q.length<48)q.push({damage,pierce,time,wave:s.enemy.wave,source:i.id})}
function wandDamage(i,total){const m=defs[i.type].mechanic,state=specialState(i),phases=state.wandPhases||(state.wandPhases=m.components.map(c=>1-c.rate)),parts=[];let weight=0;
 for(let n=0;n<m.components.length;n++){const c=m.components[n];phases[n]+=c.rate;if(phases[n]+1e-8<1)continue;phases[n]-=1;if(c.frontOnly&&i.y!==0)continue;parts.push(c);weight+=c.weight}
 state.lastVolleyShots=m.pattern?m.pattern[(i.activations-1)%m.pattern.length]:parts.reduce((n,c)=>n+c.count,0);if(m.pulseSizes)state.lastPulseSize=m.pulseSizes[(i.activations-1)%m.pulseSizes.length];
 const pattern=m.pattern?state.lastVolleyShots/m.patternMean:1,roll=m.rolls?m.rolls[(i.activations-1)%m.rolls.length]/m.rollMean:1,position=m.closeRing&&i.y!==0?.4:m.radial&&i.y!==0?1/3:1,budget=Math.max(0,Math.round((total*weight/m.expectedWeight*pattern*roll+s.power)*position)),full=weight||1;let dealt=0,used=0;
 for(const c of parts){const next=used+c.weight,damage=Math.floor(budget*next/full)-Math.floor(budget*used/full);used=next;if(c.delay)wandQueue(i,damage,c.pierce,c.delay);else if(c.returning){const back=Math.floor(damage/2);dealt+=swordHit(damage-back,c.pierce);wandQueue(i,back,c.pierce,.35)}else dealt+=swordHit(damage,c.pierce)}
 if(m.curse&&wandCurseActive())dealt+=swordHit(20,1);return dealt
}
function wandReady(key,lock){const locks=s.wandLocks||(s.wandLocks={});if(s.time<(locks[key]||0))return false;locks[key]=s.time+lock;return true}
function wandField(i,kind,total,duration,steps,delay=0){const fields=s.wandFields||(s.wandFields=[]);s.wandFields=fields.filter(p=>p.kind!==kind);if(s.wandFields.length<8)s.wandFields.push({source:i.id,wave:s.enemy.wave,kind,total,duration,steps,elapsed:-delay,pulses:0})}
function wandAfterActivation(i){const m=defs[i.type].mechanic,state=specialState(i);
 if(m.wandMana)gainMana(m.wandMana,i);
 if(m.discount)s.wandWisdomUntil=s.time+1;
 if(m.vitalityLock&&wandReady(swordBaseName(i)+':vitality',m.vitalityLock))restore(1,true,i);
 if(m.waterBurst&&wandReady('water',3))swordHit(m.waterBurst);
 if(m.pool&&wandReady('pool',2))wandField(i,'pool',9,3,3,.4);
 if(m.square&&wandReady('square',1))wandField(i,'square',Math.round(16*(1+(m.ownAttack||0))+Math.min(8,s.power/5)),1.6,8);
 if(m.wandNovaDamage&&(i.y===0||realmSetCount('geb')===4)&&wandReady('gebNova',5)){swordHit(m.wandNovaDamage);s.enemy.chill=Math.max(s.enemy.chill,m.novaChill)}
 if(m.bleed){const add=Math.max(0,Math.min(m.bleed,6-s.enemy.bleed));if(add)apply('bleed',add,i)}
 if(m.berserk){state.berserkCharge=(state.berserkCharge||0)+3*state.lastVolleyShots;if(state.berserkCharge>=100){state.berserkCharge-=100;state.berserkUntil=s.time+2}}
 if(m.abomination){state.manaCharge=(state.manaCharge||0)+5;if((s.slow>0||state.manaCharge>=100)&&wandReady('abominationMana',.2)){if(state.manaCharge>=100)state.manaCharge-=100;gainMana(3,i)}}
 if(m.soul){const charge=(state.soulCharge||0)+15;state.soulCharge=Math.min(100,charge);const limit=m.soul==='desperate'?1:2;if(state.soulCharge>=100&&s.summons.length<8&&s.summons.filter(p=>p.wandSoul===m.soul).length<limit&&wandReady(m.soul,m.soul==='desperate'?.6:.4)){state.soulCharge=charge-100;s.summons.push({wandSoul:m.soul,power:0,duration:m.soul==='desperate'?10:8,elapsed:0,impact:false,exposed:false,ownerId:i.id,wave:s.enemy.wave});itemFxPulse(i,'summon','✦')}}
}
function wandAbilityEvent(source){if(!source||defs[source.type].group!=='ability'||!s.items.includes(source))return;const cursed=s.items.find(i=>defs[i.type].mechanic?.curse),fort=s.items.find(i=>defs[i.type].mechanic?.fortitude),discount=s.items.find(i=>defs[i.type].mechanic?.discount);
 if(cursed){s.wandCurseCharge=Math.min(100,(s.wandCurseCharge||0)+40);if(s.wandCurseCharge>=100&&wandReady('curse',5)){s.wandCurseCharge-=100;s.wandCurseUntil=s.time+4;itemFxPulse(cursed,'utility','✦')}}
 if(fort&&wandReady('fortitude',15))for(let n=0;n<3;n++)wandQueue(fort,8,0,n*.4);
 if(discount){s.wandDiscountCarry=(s.wandDiscountCarry||0)+itemManaCost(defs[source.type],source)*.05;const refund=Math.floor(s.wandDiscountCarry+1e-8);if(refund){s.wandDiscountCarry=Math.max(0,s.wandDiscountCarry-refund);gainMana(refund,discount)}}
}
function wandCurseActive(){return s.time<(s.wandCurseUntil||0)&&s.items.some(i=>defs[i.type].mechanic?.curse)}
function wandIncomingMultiplier(){return wandCurseActive()?1.15:1}
function wandManaSuppressed(){return s.time<(s.wandWisdomUntil||0)&&s.items.some(i=>defs[i.type].mechanic?.discount)}
function wandRecovery(i){const m=defs[i.type].mechanic;return m?.wand&&m.burstCount&&i.activations>0&&i.activations%m.burstCount===0}
function wandCooldown(i,base){return wandRecovery(i)?defs[i.type].mechanic.burstRest:base}
function wandRechargeStep(i,dt){if(!defs[i.type].mechanic?.berserk||!(i.special?.berserkUntil>0))return dt;const active=Math.max(0,Math.min(dt,i.special.berserkUntil-Math.max(0,s.time-dt)));return dt+active*.25}
function wandCooldownFloor(i){return wandRecovery(i)?defs[i.type].mechanic.burstFloor:0}
function resetWandMechanics(){s.wandProjectiles=[];s.wandFields=[];s.wandLocks={};s.wandCurseCharge=0;s.wandCurseUntil=0;s.wandWisdomUntil=0;s.wandDiscountCarry=0}
function tickWandMechanics(dt){const valid=p=>p.wave===s.enemy.wave&&s.items.some(i=>i.id===(p.source??p.ownerId));
 for(const p of s.wandProjectiles||[]){p.time-=dt;if(p.time<=1e-8&&valid(p))swordHit(p.damage,p.pierce)}s.wandProjectiles=(s.wandProjectiles||[]).filter(p=>p.time>1e-8&&valid(p));
 for(const p of s.wandFields||[]){if(!valid(p))continue;p.elapsed=Math.min(p.duration,p.elapsed+dt);while(p.pulses<p.steps&&(p.pulses+1)*p.duration/p.steps<=p.elapsed+1e-8){const before=Math.floor(p.total*p.pulses/p.steps);p.pulses++;swordHit(Math.floor(p.total*p.pulses/p.steps)-before)}}s.wandFields=(s.wandFields||[]).filter(p=>valid(p)&&p.pulses<p.steps);
 for(const p of s.summons){if(!p.wandSoul)continue;if(!valid(p)){p.duration=0;continue}p.elapsed+=dt;if(!p.impact&&p.elapsed+1e-8>=.4){p.impact=true;swordHit(p.wandSoul==='desperate'?13:4)}if(!p.exposed&&p.elapsed+1e-8>=(p.wandSoul==='desperate'?6:5)){p.exposed=true;s.enemy.vulnerable=Math.max(s.enemy.vulnerable,p.wandSoul==='desperate'?2:4)}if(p.elapsed+1e-8>=(p.wandSoul==='desperate'?10:8))p.duration=0}
 s.summons=s.summons.filter(p=>!p.wandSoul||p.duration>0)
}
function wandStateText(i){const m=defs[i.type].mechanic,state=specialState(i),parts=[];if(m.soul)parts.push('Soul charge: '+(state.soulCharge||0)+'/100');if(m.burstCount)parts.push(wandRecovery(i)?'Burst recovery':'Burst: '+(i.activations%m.burstCount)+'/'+m.burstCount);if(m.curse)parts.push(wandCurseActive()?'Forbidden curse active':'Curse charge: '+(s.wandCurseCharge||0)+'/100');if(m.discount)parts.push('Mana refund credit: '+Math.round((s.wandDiscountCarry||0)*100)+'%');if(m.berserk)parts.push(s.time<(state.berserkUntil||0)?'Berserk: +25% own recharge':'Berserk charge: '+(state.berserkCharge||0)+'/100');if(m.pulseSizes)parts.push('Shot size: '+(state.lastPulseSize||50));if(m.pattern)parts.push('Next fan: '+m.pattern[i.activations%m.pattern.length]+' shots');if(m.closeRing||m.radial||m.components.some(c=>c.frontOnly))parts.push(i.y===0?'Full close-range volley':'Outer hits only');return parts.join(' · ')}
